// Grammar of the Practice-1 book lessons (from the book's table of contents; explanations + examples by local AI, reviewed). Key: lesson number.
export const szGrammar: Record<number, { pattern: string; nameEn: string; explanation: string; explanationRu: string; examples: { zh: string; en: string; ru: string }[] }[]> = {
  1: [{"pattern":"叫","nameEn":"Verb 'call'","explanation":"The verb '叫' means 'to call' or 'to be called'. It is used to state someone's name or title. The structure is Subject + 叫 + Name/Title.","explanationRu":"","examples":[{"zh":"我叫李明。","en":"My name is Li Ming.","ru":"Меня зовут Ли Мин."},{"zh":"他叫张华。","en":"His name is Zhang Hua.","ru":"Его зовут Чжан Хуа."},{"zh":"这个城市叫约翰内斯堡。","en":"This city is called Johannesburg.","ru":"Этот город называется Йоханнесбург."}]},{"pattern":"是","nameEn":"'is' sentence","explanation":"The '是' sentence structure is used to state identity or characteristics. The structure is Subject + 是 + Complement. It is often used for definitions or descriptions.","explanationRu":"","examples":[{"zh":"我是学生。","en":"I am a student.","ru":"Я студент."},{"zh":"他是老师。","en":"He is a teacher.","ru":"Он учитель."},{"zh":"南非是非洲的一个国家。","en":"South Africa is a country in Africa.","ru":"Южная Африка — страна в Африке."}]},{"pattern":"也","nameEn":"Adverb 'also'","explanation":"The adverb '也' means 'also' or 'too'. It is placed before the verb or adjective to indicate that something applies to another person or thing as well. It is often used in positive statements.","explanationRu":"","examples":[{"zh":"我也是中国人。","en":"I am also Chinese.","ru":"Я тоже китаец."},{"zh":"她也喜欢中国。","en":"She also likes China.","ru":"Она тоже любит Китай."},{"zh":"南非也说英语。","en":"South Africa also speaks English.","ru":"Южная Африка тоже говорит по-английски."}]}],
  2: [{"pattern":"谁","nameEn":"Interrogative Pronoun 'who'","explanation":"Used to ask about a person. It is placed before the verb in a question. Commonly used in questions like 'Who is it?' or 'Who did it?'.","explanationRu":"","examples":[{"zh":"谁是我的朋友？","en":"Who is my friend?","ru":"Кто мой друг?"},{"zh":"谁在打电话？","en":"Who is on the phone?","ru":"Кто звонит?"},{"zh":"谁是老师？","en":"Who is the teacher?","ru":"Кто учитель?"}]},{"pattern":"吧","nameEn":"Modal Particle 'ba'","explanation":"Used to make suggestions or soften a statement. It is often added at the end of a sentence. Commonly used in phrases like 'Let's go' or 'It's nice, isn't it?'.","explanationRu":"","examples":[{"zh":"我们去吃饭吧。","en":"Let's go eat.","ru":"Давай поедим."},{"zh":"你去吧。","en":"You go.","ru":"Ты иди."}]}],
  3: [{"pattern":"要 + 动词","nameEn":"Auxiliary Verb '要'","explanation":"Used to express future intention or desire. Followed by a verb. The structure is '要 + verb'. It is commonly used for plans or requests.","explanationRu":"","examples":[{"zh":"我明天要去超市。","en":"I am going to the supermarket tomorrow.","ru":"Я завтра пойду в супермаркет."},{"zh":"你要喝牛奶吗？","en":"Do you want to drink milk?","ru":"Хочешь ли ты пить молоко?"},{"zh":"他要买新椅子。","en":"He wants to buy a new chair.","ru":"Он хочет купить новый стул."}]},{"pattern":"多少 + 量词 + 名词","nameEn":"Interrogative Pronoun '多少'","explanation":"Used to ask about quantity or amount. Followed by a measure word and a noun. Typically used for countable items.","explanationRu":"","examples":[{"zh":"这个垃圾桶多少钱？","en":"How much is this trash can?","ru":"Сколько стоит этот мусорный бак?"},{"zh":"你要多少块毛巾？","en":"How many towels do you need?","ru":"Сколько полотенец тебе нужно?"},{"zh":"这个塑料袋多少钱？","en":"How much is this plastic bag?","ru":"Сколько стоит этот пластиковый пакет?"}]},{"pattern":"数字 + 量词 + 名词","nameEn":"Expressions About Numbers","explanation":"Used to express quantities. Followed by a measure word and a noun. Common in daily conversations for counting items.","explanationRu":"","examples":[{"zh":"我需要两把椅子。","en":"I need two chairs.","ru":"Мне нужно два стула."},{"zh":"这里有三张桌子。","en":"There are three tables here.","ru":"Здесь три стола."},{"zh":"我要买四块毛巾。","en":"I want to buy four towels.","ru":"Я хочу купить четыре полотенца."}]},{"pattern":"量词 + 名词","nameEn":"Measure Words","explanation":"Measure words are used before nouns to indicate quantity. Each noun has a specific measure word. Common measure words include '把' for chairs, '张' for tables, '块' for towels.","explanationRu":"","examples":[{"zh":"这把椅子很舒服。","en":"This chair is comfortable.","ru":"Этот стул очень удобный."},{"zh":"那张桌子很大。","en":"That table is big.","ru":"Тот стол большой."},{"zh":"我需要一块毛巾。","en":"I need a towel.","ru":"Мне нужно полотенце."}]},{"pattern":"再 + 动词","nameEn":"Adverb '再'","explanation":"Used to indicate repetition or continuation. Followed by a verb. Often used with '请' or '不' to form polite requests or negative statements.","explanationRu":"","examples":[{"zh":"请再给我一杯牛奶。","en":"Please give me another glass of milk.","ru":"Пожалуйста, дайте мне ещё один стакан молока."},{"zh":"你再等一下，我马上来。","en":"Wait a moment, I'll be right there.","ru":"Подожди немного, я сейчас приду."},{"zh":"不要再迟到了。","en":"Don't be late again.","ru":"Не опаздывай снова."}]}],
  4: [{"pattern":"有","nameEn":"Existential 'There is/are' Sentence","explanation":"The structure '有' is used to express existence, meaning 'there is/are'. It is followed by a noun phrase. The word order is: Subject + 有 + Noun Phrase. It is commonly used to state what exists in a place or situation.","explanationRu":"","examples":[{"zh":"我家有三口人。","en":"There are three people in my family.","ru":"В моей семье три человека."},{"zh":"北京有好多博物馆。","en":"There are many museums in Beijing.","ru":"В Пекине много музеев."},{"zh":"他有一辆自行车。","en":"He has a bicycle.","ru":"У него есть велосипед."}]},{"pattern":"还","nameEn":"Adverb 'Still/Also'","explanation":"The adverb '还' is used to indicate continuation or addition, meaning 'still' or 'also'. It is placed before the verb or adjective. It often expresses that something continues to be true or adds another detail.","explanationRu":"","examples":[{"zh":"我还会说英语。","en":"I can also speak English.","ru":"Я также умею говорить по-английски."},{"zh":"他还很年轻。","en":"He is still very young.","ru":"Он все еще очень молод."},{"zh":"我们还想去北京。","en":"We also want to go to Beijing.","ru":"Мы также хотим поехать в Пекин."}]}],
  5: [{"pattern":"时间表达法","nameEn":"Expressions About Time","explanation":"Time expressions in Chinese are used to indicate when something happens. They usually come before the verb and can include specific times, days, or periods. Common time words include 早上 (morning), 下午 (afternoon), and 晚上 (evening).","explanationRu":"","examples":[{"zh":"我早上六点起床。","en":"I get up at six in the morning.","ru":"Я встаю в шесть утра."},{"zh":"我们下午三点开会。","en":"We have a meeting at three in the afternoon.","ru":"Мы встречаемся в три часа дня."},{"zh":"她晚上八点看电影。","en":"She watches a movie at eight in the evening.","ru":"Она смотрит фильм в восемь часов вечера."}]},{"pattern":"时间状语","nameEn":"Adverbial of Time","explanation":"An adverbial of time modifies a verb to show when an action occurs. It is often placed at the beginning of a sentence or before the verb. Common time adverbs include 早上, 下午, and 晚上.","explanationRu":"","examples":[{"zh":"早上我吃早饭。","en":"In the morning, I eat breakfast.","ru":"Утром я завтракаю."},{"zh":"下午我们爬山。","en":"In the afternoon, we go hiking.","ru":"Днем мы идем на гору."},{"zh":"晚上她学习汉语。","en":"In the evening, she studies Chinese.","ru":"Вечером она изучает китайский язык."}]},{"pattern":"几点+V","nameEn":"\"几点+V\" Sentence","explanation":"The structure '几点+V' is used to ask or state the time of an action. '几点' means 'what time', and it is followed by a verb. This structure is common for daily routines.","explanationRu":"","examples":[{"zh":"你几点起床？","en":"What time do you get up?","ru":"Во сколько ты встаешь?"},{"zh":"我早上七点吃早饭。","en":"I eat breakfast at seven in the morning.","ru":"Я завтракаю в семь утра."},{"zh":"她几点开始工作？","en":"What time does she start working?","ru":"Во сколько она начинает работать？"}]}],
  6: [{"pattern":"……的东边/西边/南边/北边","nameEn":"Directional Location","explanation":"This structure shows the location of something relative to a direction (east, west, south, north). The word '的' connects the location to the direction. It is used to describe where a place is located in relation to another place.","explanationRu":"","examples":[{"zh":"北京的东边有天安门广场。","en":"The East side of Beijing has Tiananmen Square.","ru":"На востоке Пекина находится площадь Тяньаньмэнь."},{"zh":"上海的西边是苏州。","en":"The West side of Shanghai is Suzhou.","ru":"На западе Шанхая находится Сучжоу."},{"zh":"我家的南边是公园。","en":"The South side of my house is a park.","ru":"На юге моего дома находится парк."}]},{"pattern":"在","nameEn":"Preposition 'at' / 'in'","explanation":"The preposition '在' is used to indicate location or position. It is placed before a location noun to show where something is located. It is commonly used with places like cities, buildings, and streets.","explanationRu":"","examples":[{"zh":"我在北京。","en":"I am in Beijing.","ru":"Я нахожусь в Пекине."},{"zh":"图书馆在学校的东边。","en":"The library is east of the school.","ru":"Библиотека находится на востоке от школы."},{"zh":"餐厅在商场的二楼。","en":"The restaurant is on the second floor of the mall.","ru":"Ресторан находится на втором этаже торгового центра."}]},{"pattern":"想","nameEn":"Auxiliary Verb 'want' / 'would like'","explanation":"The auxiliary verb '想' is used to express a desire or intention to do something. It comes before the main verb in a sentence. It is commonly used to express what someone wants to do or what they would like to do.","explanationRu":"","examples":[{"zh":"我想去北京。","en":"I want to go to Beijing.","ru":"Я хочу поехать в Пекин."},{"zh":"她想吃中国菜。","en":"She wants to eat Chinese food.","ru":"Она хочет поесть китайской еды."},{"zh":"我们想参观故宫。","en":"We want to visit the Forbidden City.","ru":"Мы хотим посетить Запретный город."}]},{"pattern":"……在哪儿？","nameEn":"Interrogative Sentence 'Where is...?'","explanation":"This question structure is used to ask about the location of something. It is formed by placing '在哪儿' after the subject. It is commonly used to ask where a place or object is located.","explanationRu":"","examples":[{"zh":"宾馆在哪儿？","en":"Where is the hotel?","ru":"Где находится отель?"},{"zh":"加油站在哪里？","en":"Where is the gas station?","ru":"Где находится автозаправка?"},{"zh":"大使馆在哪儿？","en":"Where is the embassy?","ru":"Где находится посольство?"}]}],
  8: [{"pattern":"正在","nameEn":"Adverb '正在'","explanation":"Used to indicate an action happening right now. It is placed before the verb. Commonly used in present continuous tense.","explanationRu":"","examples":[{"zh":"他正在吃饭。","en":"He is eating now.","ru":"Он сейчас ест."},{"zh":"我们正在学习中文。","en":"We are learning Chinese now.","ru":"Мы сейчас изучаем китайский язык."},{"zh":"她正在打电话。","en":"She is on the phone now.","ru":"Она сейчас говорит по телефону."}]},{"pattern":"请","nameEn":"Verb '请'","explanation":"Used to make a polite request or invitation. Placed before the verb.","explanationRu":"","examples":[{"zh":"请坐。","en":"Please sit down.","ru":"Пожалуйста, садитесь."},{"zh":"请帮我拿一下包。","en":"Please help me carry the bag.","ru":"Пожалуйста, помогите мне взять сумку."},{"zh":"请慢走。","en":"Take care (said to a guest who is leaving).","ru":"Пожалуйста, идите медленно."}]},{"pattern":"刚","nameEn":"Adverb '刚'","explanation":"Used to indicate that something just happened. Placed before the verb.","explanationRu":"","examples":[{"zh":"我刚到家。","en":"I just got home.","ru":"Я только что приехал домой."},{"zh":"他刚吃完饭。","en":"He just finished eating.","ru":"Он только что закончил есть."},{"zh":"我刚认识了新朋友。","en":"I just made a new friend.","ru":"Я только что познакомился с новым другом."}]},{"pattern":"不太 +A/V","nameEn":"Fixed Pattern '不太 +A/V'","explanation":"Used to express that something is not very much or not very good. '不太' is placed before an adjective or verb.","explanationRu":"","examples":[{"zh":"这个菜不太好吃。","en":"This dish is not very tasty.","ru":"Это блюдо не очень вкусное."},{"zh":"他不太喜欢这个电影。","en":"He doesn't like this movie very much.","ru":"Он не очень любит этот фильм."},{"zh":"我的收入不太高。","en":"My income is not very high.","ru":"Моя зарплата не очень высокая."}]}],
  9: [{"pattern":"动词重叠（VV）","nameEn":"Reduplication of Verbs","explanation":"Verbs can be repeated to indicate a short, repeated action or a gentle, ongoing action. The structure is VV, with no change in meaning. It is commonly used in informal speech.","explanationRu":"","examples":[{"zh":"我们先走走吧。","en":"Let's take a little walk first.","ru":"Давайте сначала прогуляемся."},{"zh":"你再看看吧。","en":"Take another look.","ru":"Посмотри еще раз."}]},{"pattern":"先……，然后……","nameEn":"Complex Sentence of Successive Relation","explanation":"This structure is used to describe a sequence of actions. It means 'first... then...'. The structure is 先 V1，然后 V2.","explanationRu":"","examples":[{"zh":"先吃饭，然后去公园。","en":"First eat, then go to the park.","ru":"Сначала поешь, потом пойдешь в парк."},{"zh":"先看菜单，然后点菜。","en":"First look at the menu, then order.","ru":"Сначала посмотрите меню, потом заказывайте."}]},{"pattern":"跟……一起","nameEn":"Fixed Pattern","explanation":"This pattern means 'with' or 'together with'. It is used to indicate someone or something that accompanies the subject.","explanationRu":"","examples":[{"zh":"我跟朋友一起吃饭。","en":"I eat with my friend.","ru":"Я ем с другом."},{"zh":"他跟家人一起住。","en":"He lives with his family.","ru":"Он живет с семьей."}]},{"pattern":"和……一样","nameEn":"Fixed Pattern","explanation":"This pattern means 'the same as' or 'like'. It is used to compare two things.","explanationRu":"","examples":[{"zh":"这个沙发和那个沙发一样舒服。","en":"This sofa is as comfortable as that one.","ru":"Этот диван такой же удобный, как тот."},{"zh":"他的态度和她一样礼貌。","en":"His attitude is as polite as hers.","ru":"Его отношение такое же вежливое, как и ее."},{"zh":"这个中餐厅和那个中餐厅一样好。","en":"This Chinese restaurant is as good as that one.","ru":"Этот китайский ресторан такой же хороший, как и тот."}]}],
  10: [{"pattern":"最","nameEn":"Adverb of Degree 'Most'","explanation":"Used to indicate the highest degree of an adjective. It comes before the adjective and is often used for comparison. It is not used with adjectives that already have a comparative form.","explanationRu":"","examples":[{"zh":"北京的故宫最漂亮。","en":"The Forbidden City in Beijing is the most beautiful.","ru":"Запретный город в Пекине самый красивый."},{"zh":"这个苹果最甜。","en":"This apple is the sweetest.","ru":"Это яблоко самое сладкое."}]},{"pattern":"怎么样","nameEn":"Interrogative Pronoun 'How'","explanation":"Used to ask about the condition or quality of something. Often used with '怎么样' to mean 'how is it?' or 'what's the situation?'.","explanationRu":"","examples":[{"zh":"今天天气怎么样？","en":"How is the weather today?","ru":"Как погода сегодня?"},{"zh":"这个景点怎么样？","en":"How is this scenic spot?","ru":"Как вам эта достопримечательность?"},{"zh":"你的计划怎么样？","en":"How is your plan?","ru":"Какой ваш план?"}]},{"pattern":"快要/要……了","nameEn":"Fixed Usage 'Almost/Going to...'","explanation":"Used to indicate that something is about to happen or is almost happening. '快要' is used for something that is nearly happening, and '要' is used for something that will happen soon.","explanationRu":"","examples":[{"zh":"暑假快要到了。","en":"Summer vacation is almost here.","ru":"Каникулы почти придут."},{"zh":"我们快要到学校了。","en":"We are almost at school.","ru":"Мы почти приехали в школу."},{"zh":"明天要下雨了。","en":"It will rain tomorrow.","ru":"Завтра пойдет дождь."}]}],
  11: [{"pattern":"可是","nameEn":"Adverb 'but' / 'however'","explanation":"Used to show contrast between two ideas. Comes after a statement and before another statement. Often used in spoken language.","explanationRu":"","examples":[{"zh":"我想去公园，可是下雨了。","en":"I wanted to go to the park, but it rained.","ru":"Я хотел пойти в парк, но пошел дождь."},{"zh":"他很忙，可是还是来参加了会议。","en":"He was busy, but he still came to the meeting.","ru":"Он был занят, но всё-таки пришел на собрание."},{"zh":"这个价格很贵，可是质量很好。","en":"This price is expensive, but the quality is good.","ru":"Эта цена высокая, но качество хорошее."}]},{"pattern":"好像","nameEn":"Adverb 'seem' / 'it seems'","explanation":"Used to express that something appears to be true, but it's not certain. Often used with '好像' + [sentence].","explanationRu":"","examples":[{"zh":"他好像很累。","en":"He seems very tired.","ru":"Он кажется очень усталым."},{"zh":"今天好像会下雨。","en":"It seems it will rain today.","ru":"Сегодня, кажется, будет дождь."},{"zh":"这个数字好像不对。","en":"This number seems wrong.","ru":"Это число кажется неправильным."}]}],
  12: [{"pattern":"比","nameEn":"Comparative Structure with 'Bi'","explanation":"The '比' structure compares two things, with the structure: Subject + 比 + Object + Adjective/Verb. It is used to show that one thing is more or less than another in a specific quality.","explanationRu":"","examples":[{"zh":"我的书比你的书贵。","en":"My book is more expensive than yours.","ru":"Моя книга дороже твоей."},{"zh":"他比我高。","en":"He is taller than me.","ru":"Он выше меня."},{"zh":"这个苹果比那个苹果大。","en":"This apple is bigger than that one.","ru":"Это яблоко больше того."}]},{"pattern":"看起来","nameEn":"Adverb 'Kan' (Looks Like)","explanation":"The phrase '看起来' is used before an adjective to mean 'looks like' or 'seems to be'. It is often used to describe appearance or general impression.","explanationRu":"","examples":[{"zh":"她看起来很年轻。","en":"She looks very young.","ru":"Она выглядит очень молодой."},{"zh":"这个房间看起来很干净。","en":"This room looks very clean.","ru":"Эта комната выглядит очень чистой."},{"zh":"他看起来很累。","en":"He looks very tired.","ru":"Он выглядит очень усталым."}]},{"pattern":"挺","nameEn":"Adverb of Degree 'Ting'","explanation":"The adverb '挺' is used before adjectives to mean 'quite' or 'fairly'. It is informal and commonly used in spoken Chinese.","explanationRu":"","examples":[{"zh":"这个电影挺好看。","en":"This movie is quite good.","ru":"Этот фильм довольно хорош."},{"zh":"天气挺热的。","en":"The weather is quite hot.","ru":"Погода довольно жаркая."},{"zh":"他挺高的。","en":"He is quite tall.","ru":"Он довольно высокий."}]},{"pattern":"应该","nameEn":"Auxiliary Verb 'Yinggai'","explanation":"The auxiliary verb '应该' is used to express obligation, recommendation, or expectation. It is often translated as 'should' or 'ought to'.","explanationRu":"","examples":[{"zh":"你应该早点起床。","en":"You should get up early.","ru":"Ты должен встать рано."},{"zh":"他应该会来。","en":"He should come.","ru":"Он должен прийти."},{"zh":"我们应该帮助别人。","en":"We should help others.","ru":"Мы должны помогать другим."}]},{"pattern":"再","nameEn":"Adverb 'Zai' (Again/More)","explanation":"The adverb '再' is used to mean 'again' or 'more'. It is often used in the context of doing something one more time or adding something to a previous action.","explanationRu":"","examples":[{"zh":"我再吃一个苹果。","en":"I will eat one more apple.","ru":"Я съем еще одно яблоко."},{"zh":"请再等一下。","en":"Please wait a little more.","ru":"Пожалуйста, подождите еще немного."},{"zh":"明天再来看我。","en":"Come see me again tomorrow.","ru":"Приходи ко мне снова завтра."}]}],
  13: [{"pattern":"了1","nameEn":"Particle 'le1'","explanation":"Used after verbs to indicate a completed action or a change of state. It is placed after the verb and before any other elements in the sentence.","explanationRu":"","examples":[{"zh":"我完成了作业。","en":"I have finished my homework.","ru":"Я закончил домашнее задание."},{"zh":"她放弃了比赛。","en":"She gave up the competition.","ru":"Она отказалась от соревнования."},{"zh":"我们互相交流了意见。","en":"We exchanged our opinions.","ru":"Мы обменялись мнениями."}]},{"pattern":"才2","nameEn":"Adverb 'cai2'","explanation":"Used to express that something happened later than expected or after a long time. It is placed before the verb.","explanationRu":"","examples":[{"zh":"我今天才开始学习。","en":"I started studying today.","ru":"Я начал учиться сегодня."},{"zh":"他才来中国。","en":"He just came to China.","ru":"Он только что приехал в Китай."},{"zh":"我们才完成这个项目。","en":"We just finished this project.","ru":"Мы только что закончили этот проект."}]},{"pattern":"得","nameEn":"Auxiliary Verb 'de'","explanation":"Used to indicate the result or degree of an action. It is placed after the verb and before the complement.","explanationRu":"","examples":[{"zh":"他弹得非常好。","en":"He plays the piano very well.","ru":"Он играет на пианино очень хорошо."},{"zh":"我们适应得很快。","en":"We adapted quickly.","ru":"Мы быстро приспособились."},{"zh":"她考虑得非常周到。","en":"She thought very carefully.","ru":"Она подумала очень обдуманно."}]},{"pattern":"离","nameEn":"Verb 'li2'","explanation":"Means 'to leave' or 'to be away from'. It is used to indicate distance or separation.","explanationRu":"","examples":[{"zh":"我家离学校很近。","en":"My home is close to the school.","ru":"Мой дом находится недалеко от школы."},{"zh":"他们离得远。","en":"They are far apart.","ru":"Они находятся далеко друг от друга."},{"zh":"我离家已经三年了。","en":"I have been away from home for three years.","ru":"Я уехал из дома уже три года."}]},{"pattern":"怎么","nameEn":"Interrogative Pronoun 'zen2me'","explanation":"Used to ask 'how' or 'why'. It is placed at the beginning of a question.","explanationRu":"","examples":[{"zh":"你怎么不去学校？","en":"Why don't you go to school?","ru":"Почему ты не ходишь в школу?"},{"zh":"你怎么想的？","en":"What do you think?","ru":"Что ты думаешь?"},{"zh":"怎么了？","en":"What's wrong?","ru":"Что случилось?"}]}],
  14: [{"pattern":"动量词（Verbal Measure Words） “趟、遍”","nameEn":"Verbal Measure Words 'tang', 'bian'","explanation":"Verbal measure words 'tang' and 'bian' are used after verbs to indicate the number of times an action is done. 'Tang' is used for actions that involve moving from one place to another, while 'bian' is used for actions that are repeated or done multiple times.","explanationRu":"","examples":[{"zh":"我每天去公司一趟。","en":"I go to the company once a day.","ru":"Я хожу в компанию один раз в день."},{"zh":"他读了这本书两遍。","en":"He read this book two times.","ru":"Он прочитал эту книгу два раза."},{"zh":"我们去了公园三趟。","en":"We went to the park three times.","ru":"Мы ходили в парк три раза."}]},{"pattern":"副词（Adverb）“又”","nameEn":"Adverb 'you'","explanation":"The adverb 'you' is used to indicate that something is happening again or repeatedly, often with a sense of annoyance or surprise. It is placed before the verb.","explanationRu":"","examples":[{"zh":"他又迟到了。","en":"He is late again.","ru":"Он опоздал снова."},{"zh":"我又要加班了。","en":"I have to work overtime again.","ru":"Мне снова нужно работать сверхурочно."},{"zh":"她又买了一本书。","en":"She bought another book.","ru":"Она купила еще одну книгу."}]},{"pattern":"副词（Adverb）“大概”","nameEn":"Adverb 'dàgài'","explanation":"The adverb 'dàgài' is used to express an approximate or estimated time, number, or quantity. It is placed before the verb or adjective.","explanationRu":"","examples":[{"zh":"会议大概在三点开始。","en":"The meeting will probably start at three o'clock.","ru":"Встреча, вероятно, начнется в три часа."},{"zh":"他大概有三十岁。","en":"He is probably around thirty years old.","ru":"Он, вероятно, около тридцати лет."},{"zh":"这个项目大概需要一个月。","en":"This project will probably take about a month.","ru":"Этот проект, вероятно, займет около месяца."}]},{"pattern":"名词（Noun）“左右”","nameEn":"Noun 'zuǒyòu'","explanation":"The noun 'zuǒyòu' is used to indicate an approximate number or time, meaning 'around' or 'approximately'. It is placed after the number or time.","explanationRu":"","examples":[{"zh":"我需要花二十分钟左右。","en":"I need about twenty minutes.","ru":"Мне нужно около двадцати минут."},{"zh":"会议在三点左右开始。","en":"The meeting will start around three o'clock.","ru":"Встреча начнется примерно в три часа."}]},{"pattern":"副词（Adverb）“不要”","nameEn":"Adverb 'bùyào'","explanation":"The adverb 'bùyào' is used to express a negative command or request, meaning 'do not' or 'don't'. It is placed before the verb.","explanationRu":"","examples":[{"zh":"不要迟到。","en":"Don't be late.","ru":"Не опаздывайте."},{"zh":"不要加班。","en":"Don't work overtime.","ru":"Не работайте сверхурочно."},{"zh":"不要担心。","en":"Don't worry.","ru":"Не беспокойтесь."}]}],
  15: [{"pattern":"了2","nameEn":"Particle 'le2'","explanation":"The particle 'le2' is used to indicate a change of state or completion of an action. It is placed after the verb or adjective. It often shows that something has happened or changed recently.","explanationRu":"","examples":[{"zh":"我学会了普通话。","en":"I have learned Putonghua.","ru":"Я выучил пущонгуа."},{"zh":"天气变冷了。","en":"The weather has become cold.","ru":"Погода стала холодной."}]},{"pattern":"像…… 一样","nameEn":"Fixed Pattern 'like...'","explanation":"The pattern '像…… 一样' means 'like' or 'as... as'. It is used to compare two things. The structure is: Subject + 像 + Comparison Item + 一样.","explanationRu":"","examples":[{"zh":"她的声音像小鸟一样动听。","en":"Her voice is as sweet as a bird's song.","ru":"Ее голос звучит так же мелодично, как пение птицы."},{"zh":"他跑得像风一样快。","en":"He runs as fast as the wind.","ru":"Он бежит так быстро, как ветер."},{"zh":"这个故事像童话一样有趣。","en":"This story is as interesting as a fairy tale.","ru":"Эта история так интересна, как сказка."}]},{"pattern":"越来越……","nameEn":"Fixed Usage '越来越...'","explanation":"The pattern '越来越……' means '越来越' (more and more) and is used to express a gradual change or increase. It is placed before an adjective or adverb.","explanationRu":"","examples":[{"zh":"天气越来越热了。","en":"The weather is getting hotter and hotter.","ru":"Погода становится все жарче и жарче."},{"zh":"他越来越喜欢中文了。","en":"He is getting more and more interested in Chinese.","ru":"Он все больше и больше любит китайский язык."},{"zh":"我们的生活越来越好了。","en":"Our lives are getting better and better.","ru":"Наша жизнь становится все лучше и лучше."}]},{"pattern":"对……有/没有好处","nameEn":"Fixed Usage 'be good/bad for...'","explanation":"The pattern '对……有/没有好处' means 'be good/bad for...'. It is used to express whether something is beneficial or not. The structure is: 对 + Object + 有/没有好处.","explanationRu":"","examples":[{"zh":"多喝水对身体有好处。","en":"Drinking more water is good for your health.","ru":"Пить больше воды полезно для вашего здоровья."},{"zh":"熬夜对身体没有好处。","en":"Staying up late is not good for your health.","ru":"Привычка не спать допоздна вредна для здоровья."},{"zh":"学习新语言对大脑有好处。","en":"Learning a new language is good for your brain.","ru":"Изучение нового языка полезно для вашего мозга."}]},{"pattern":"因为……，所以……","nameEn":"Complex Sentence of Causative Relation 'Because... so...'","explanation":"The pattern '因为……，所以……' means 'Because... so...'. It is used to express a cause and effect relationship. The structure is: 因为 + Cause + ，所以 + Effect.","explanationRu":"","examples":[{"zh":"因为下雨了，所以我不去公园。","en":"Because it is raining, I am not going to the park.","ru":"Потому что идет дождь, я не иду в парк."},{"zh":"因为他很努力，所以成绩很好。","en":"Because he works hard, his grades are good.","ru":"Потому что он усердно работает, его оценки хорошие."},{"zh":"因为时间不够，所以我们没有完成作业。","en":"Because we didn't have enough time, we didn't finish the homework.","ru":"Так как у нас не хватило времени, мы не закончили домашнее задание."}]}],
  16: [{"pattern":"得","nameEn":"Structural Particle 'de'","explanation":"The particle '得' is used after a verb to introduce a complement that describes the degree or manner of the action. It is placed between the verb and the complement.","explanationRu":"","examples":[{"zh":"他跑得很快。","en":"He runs very fast.","ru":"Он бежит очень быстро."},{"zh":"她唱得真好听。","en":"She sings very beautifully.","ru":"Она поет очень красиво."},{"zh":"我学得很快。","en":"I learn quickly.","ru":"Я учу быстро."}]}],
  17: [{"pattern":"是…… 的","nameEn":"Fixed Pattern 'is...'","explanation":"This pattern is used to emphasize a specific time, place, or manner. The structure is '是 + [time/place/manner] + 的'. It is commonly used in spoken Chinese to highlight a particular detail.","explanationRu":"","examples":[{"zh":"他是在北京出生的。","en":"He was born in Beijing.","ru":"Он родился в Пекине."},{"zh":"这个故事是昨天发生的。","en":"This story happened yesterday.","ru":"Эта история произошла вчера."}]},{"pattern":"够","nameEn":"Verb 'enough'","explanation":"The verb '够' means 'to be enough' or 'to suffice'. It is used to indicate that something meets a requirement or is sufficient for a purpose.","explanationRu":"","examples":[{"zh":"这个房间够大了。","en":"This room is big enough.","ru":"Эта комната достаточно большая."},{"zh":"你吃够了吗？","en":"Have you eaten enough?","ru":"Ты достаточно поел?"},{"zh":"钱够买这本书。","en":"The money is enough to buy this book.","ru":"Денег хватит на покупку этой книги."}]},{"pattern":"咱们","nameEn":"Personal Pronoun 'we' (inclusive)","explanation":"The pronoun '咱们' is used to include both the speaker and the listener in the group, often used in informal contexts. It is more casual than '我们'.","explanationRu":"","examples":[{"zh":"咱们一起去吃饭吧。","en":"Let's go eat together.","ru":"Давай пойдем вместе пообедаем."},{"zh":"咱们明天见。","en":"See you tomorrow.","ru":"Увидимся завтра."},{"zh":"咱们都得努力工作。","en":"We all need to work hard.","ru":"Все мы должны усердно работать."}]},{"pattern":"可以","nameEn":"Auxiliary Verb 'can'","explanation":"The auxiliary verb '可以' is used to express permission, possibility, or ability. It is often used in questions and answers to indicate that something is allowed or possible.","explanationRu":"","examples":[{"zh":"我可以去吗？","en":"Can I go?","ru":"Могу я пойти?"},{"zh":"你可以先走。","en":"You can go first.","ru":"Ты можешь пойти первым."},{"zh":"这里可以停车。","en":"You can park here.","ru":"Здесь можно остановиться."}]},{"pattern":"死了","nameEn":"Complement of Degree 'dead'","explanation":"The complement '死了' is used to intensify the meaning of an adjective or verb, indicating an extreme degree. It is often used in informal speech to express strong feelings or actions.","explanationRu":"","examples":[{"zh":"我饿死了。","en":"I'm starving!","ru":"Я умираю с голоду!"},{"zh":"这个笑话太好笑了，我笑死了。","en":"This joke is so funny, I'm dying of laughter.","ru":"Этот анекдот такой смешной, я умираю со смеху."},{"zh":"他累死了。","en":"He's exhausted!","ru":"Он устал до смерти!"}]}],
  18: [{"pattern":"能（不能）","nameEn":"Auxiliary Verb 'Can (Cannot)'","explanation":"Used to express ability or possibility. '能' means 'can' and '不能' means 'cannot'. It is placed before the main verb.","explanationRu":"","examples":[{"zh":"我不能去学校。","en":"I cannot go to school.","ru":"Я не могу пойти в школу."},{"zh":"他能说中文。","en":"He can speak Chinese.","ru":"Он может говорить по-китайски."}]},{"pattern":"什么 都+V","nameEn":"Fixed Pattern 'Nothing/Everything + Verb'","explanation":"Used to mean 'nothing' or 'everything' in a negative or positive sense. '什么' means 'anything', '都' means 'all', and 'V' is the verb.","explanationRu":"","examples":[{"zh":"我什么都不会。","en":"I can't do anything.","ru":"Я ничего не могу сделать."},{"zh":"他什么都能做。","en":"He can do everything.","ru":"Он может сделать всё."},{"zh":"她什么都没吃。","en":"She ate nothing.","ru":"Она ничего не съела."}]},{"pattern":"只有……，才……","nameEn":"Conditional Sentence 'Only... Then...'","explanation":"Used to express a condition that must be met before something else happens. '只有' means 'only', '才' means 'then'.","explanationRu":"","examples":[{"zh":"只有努力学习，才能取得好成绩。","en":"Only by studying hard can you get good grades.","ru":"Только усердно учась, можно получить хорошие оценки."},{"zh":"只有你来，我才去。","en":"I will go only if you come.","ru":"Я пойду только если ты приедешь."},{"zh":"只有坚持，才能成功。","en":"Only by persisting can you succeed.","ru":"Только упорствуя, можно добиться успеха."}]},{"pattern":"最好","nameEn":"Adverb 'Best'","explanation":"Used to suggest the best option or to give advice. It means 'best' or 'it's best to'.","explanationRu":"","examples":[{"zh":"最好早点去。","en":"It's best to go early.","ru":"Лучше пойти рано."},{"zh":"最好别去那里。","en":"It's best not to go there.","ru":"Лучше не ходить туда."},{"zh":"最好多休息。","en":"It's best to rest more.","ru":"Лучше отдохнуть больше."}]},{"pattern":"怪不得","nameEn":"Adverb 'No Wonder'","explanation":"Used to express that something is not surprising or to explain a situation. It means 'no wonder' or 'it's not surprising'.","explanationRu":"","examples":[{"zh":"怪不得他迟到了。","en":"No wonder he was late.","ru":"Незачем удивляться, что он опоздал."},{"zh":"怪不得她生气了。","en":"No wonder she's angry.","ru":"Не удивительно, что она разозлилась."},{"zh":"怪不得我这么难受。","en":"No wonder I feel so bad.","ru":"Не удивительно, что я чувствую себя так плохо."}]}],
  19: [{"pattern":"一定","nameEn":"Adverb 'certainly'","explanation":"Used to express certainty or confidence in a statement. It comes before the verb or adjective. Common in affirmative statements.","explanationRu":"","examples":[{"zh":"我一定去北京。","en":"I will definitely go to Beijing.","ru":"Я обязательно поеду в Пекин."},{"zh":"他一定很忙。","en":"He must be very busy.","ru":"Он, наверное, очень занят."},{"zh":"你一定喜欢这个电影。","en":"You must like this movie.","ru":"Ты, наверное, любишь этот фильм."}]},{"pattern":"多……啊！","nameEn":"Exclamatory Sentence 'How...!'","explanation":"Used to express admiration or surprise about something. The structure is 'How + adjective + noun + 啊!'.","explanationRu":"","examples":[{"zh":"多漂亮啊！","en":"How beautiful!","ru":"Как красиво!"},{"zh":"多好吃的宫保鸡丁啊！","en":"How delicious Kung Pao chicken is!","ru":"Какая вкусная курица гунбао!"},{"zh":"多迷人的街道啊！","en":"How charming the street is!","ru":"Как очаровательная улица!"}]},{"pattern":"还是","nameEn":"Adverb 'still' or 'rather'","explanation":"Used to indicate that something remains the same or to express a preference. Comes before the verb or adjective.","explanationRu":"","examples":[{"zh":"我还是喜欢北京。","en":"I still like Beijing.","ru":"Я все еще люблю Пекин."},{"zh":"我还是想吃麻婆豆腐。","en":"I still want to eat Mapo tofu.","ru":"Я все еще хочу есть мапо тофу."},{"zh":"我还是觉得这个方向对。","en":"I still think this direction is correct.","ru":"Я все еще думаю, что это правильное направление."}]},{"pattern":"…… 是……，就是……","nameEn":"Complex Sentence of Adversative Relation '... is ..., but ...'","explanation":"Used to show contrast between two ideas. The structure is '... is ..., but ...'.","explanationRu":"","examples":[{"zh":"这个地址是正确的，就是有点远。","en":"This address is correct, but it's a bit far.","ru":"Этот адрес правильный, но немного далеко."},{"zh":"他是个帅小伙，就是缺少能力。","en":"He is a handsome young man, but he lacks ability.","ru":"Он красивый парень, но ему не хватает способностей."},{"zh":"这个方向是正确的，就是我迷路了。","en":"This direction is correct, but I got lost.","ru":"Это правильное направление, но я заблудился."}]},{"pattern":"不是……吗？","nameEn":"Rhetorical Question 'Isn't it...?'","explanation":"Used to ask a question that expects a positive answer. The structure is 'Isn't it ...?'.","explanationRu":"","examples":[{"zh":"这不是宫保鸡丁吗？","en":"Isn't this Kung Pao chicken?","ru":"Разве это не курица гунбао?"},{"zh":"你不是说你来自北京吗？","en":"Didn't you say you're from Beijing?","ru":"Разве ты не говорил, что приехал из Пекина?"}]},{"pattern":"对……来说","nameEn":"Fixed Pattern 'For...'","explanation":"Used to indicate the perspective or point of view. The structure is 'For ...'.","explanationRu":"","examples":[{"zh":"对中国人来说，宫保鸡丁很受欢迎。","en":"For Chinese people, Kung Pao chicken is very popular.","ru":"Для китайцев кунг пао курица очень популярна."},{"zh":"对外国人来说，麻婆豆腐可能有点辣。","en":"For foreigners, Mapo tofu might be a bit spicy.","ru":"Для иностранцев мапо тофу может быть немного острым."},{"zh":"对来自北京的人来说，这个地址很容易找到。","en":"For people from Beijing, this address is easy to find.","ru":"Для людей из Пекина этот адрес легко найти."}]}],
  20: [{"pattern":"一边……，一边……","nameEn":"Complex Sentence of Coordinating Relation","explanation":"Used to show two actions happening at the same time. The structure is '一边 A，一边 B'. A and B are actions performed simultaneously.","explanationRu":"","examples":[{"zh":"她一边听音乐，一边写作业。","en":"She listens to music while doing her homework.","ru":"Она слушает музыку, делая уроки."},{"zh":"我们一边吃饭，一边聊天。","en":"We eat and chat at the same time.","ru":"Мы едим и разговариваем одновременно."},{"zh":"他一边走路，一边看手机。","en":"He walks while looking at his phone.","ru":"Он идет, глядя на телефон."}]},{"pattern":"一……就……","nameEn":"Complex Sentence of Successive Relation","explanation":"Used to show that one action immediately follows another. The structure is '一 A 就 B'. A happens, and then B happens right after.","explanationRu":"","examples":[{"zh":"我一到学校就交作业。","en":"As soon as I arrive at school, I hand in my homework.","ru":"Как только я прихожу в школу, я сдаю домашнюю работу."},{"zh":"他一听到消息就赶来了。","en":"He came immediately after hearing the news.","ru":"Он приехал сразу после того, как услышал новость."},{"zh":"天一黑，我们就回家。","en":"As soon as it gets dark, we go home.","ru":"Как только темнеет, мы идем домой."}]},{"pattern":"过","nameEn":"Aspectual Particle '过'","explanation":"Indicates past experience. It is placed after a verb to show that the action has been done before. The structure is 'V 过'.","explanationRu":"","examples":[{"zh":"我吃过北京烤鸭。","en":"I have eaten Peking duck before.","ru":"Я уже ел пекинскую утку."},{"zh":"你去过上海吗？","en":"Have you been to Shanghai before?","ru":"Ты был в Шанхае раньше?"},{"zh":"他学过汉语。","en":"He has studied Chinese before.","ru":"Он изучал китайский язык раньше."}]},{"pattern":"从来","nameEn":"Adverb '从来'","explanation":"Means 'never' or 'always'. It is used with negative words to emphasize that something has never happened or is always true.","explanationRu":"","examples":[{"zh":"我从来不去网吧。","en":"I never go to internet cafes.","ru":"Я никогда не хожу в интернет-кафе."},{"zh":"他从来不说谎。","en":"He never tells lies.","ru":"Он никогда не врет."},{"zh":"我从来不喜欢吃辣。","en":"I have never liked spicy food.","ru":"Я никогда не любил острое."}]},{"pattern":"都","nameEn":"Adverb '都'","explanation":"Means 'all' or 'both'. It is used before a verb or adjective to indicate that everyone or everything is included.","explanationRu":"","examples":[{"zh":"我们都喜欢看电影。","en":"We all like watching movies.","ru":"Все мы любим смотреть фильмы."},{"zh":"他们俩都去了北京。","en":"Both of them went to Beijing.","ru":"Оба они поехали в Пекин."}]}],
  21: [{"pattern":"虽然……，但是……","nameEn":"Complex Sentence of Adversative Relation","explanation":"This structure expresses contrast between two ideas. '虽然' introduces the contrast, and '但是' introduces the main point. It is used to show that despite one thing, another is true.","explanationRu":"","examples":[{"zh":"虽然下雨，但是我们还是去了公园。","en":"Although it was raining, we still went to the park.","ru":"Хотя шел дождь, мы все же пошли в парк."},{"zh":"虽然他很累，但是他还继续工作。","en":"Although he was tired, he continued working.","ru":"Хотя он устал, он продолжал работать."},{"zh":"虽然天气不好，但是比赛照常进行。","en":"Although the weather was bad, the game went on as scheduled.","ru":"Хотя погода была плохой, игра прошла по расписанию."}]},{"pattern":"以为","nameEn":"Verb '以为'","explanation":"This verb means 'to think' or 'to believe'. It is used to express a mistaken belief or assumption.","explanationRu":"","examples":[{"zh":"我以为你今天不来。","en":"I thought you weren't coming today.","ru":"Я думал, что ты сегодня не приедешь."},{"zh":"他以为我有错。","en":"He thought I was wrong.","ru":"Он думал, что я ошибся."},{"zh":"她以为我忘记了。","en":"She thought I had forgotten.","ru":"Она думала, что я забыл."}]},{"pattern":"还不……吗？","nameEn":"Rhetorical Question","explanation":"This structure is used to ask a rhetorical question, often implying that something is obvious or should be clear. It is used to express surprise or to emphasize a point.","explanationRu":"","examples":[{"zh":"你还不知道吗？","en":"Don't you know yet?","ru":"Разве ты еще не знаешь?"},{"zh":"他还不来吗？","en":"Isn't he coming yet?","ru":"Разве он еще не приехал?"},{"zh":"你还不明白吗？","en":"Don't you understand yet?","ru":"Разве ты еще не понял?"}]},{"pattern":"V+了/完……就……","nameEn":"Fixed Pattern","explanation":"This structure expresses that one action happens immediately after another. '了' or '完' indicates completion of the first action, and '就' indicates the immediate next action.","explanationRu":"","examples":[{"zh":"我吃完饭就去上班。","en":"I will go to work right after I finish eating.","ru":"Я пойду на работу сразу после того, как закончу есть."},{"zh":"他写完信就发邮件。","en":"He sent the email right after he finished writing the letter.","ru":"Он отправил письмо сразу после того, как закончил писать письмо."},{"zh":"我打印完文件就发传真。","en":"I will send the fax right after I print the document.","ru":"Я отправлю факс сразу после того, как напечатаю документ."}]}],
  22: [{"pattern":"把","nameEn":"The 'Ba' Construction","explanation":"The '把' construction is used to show that the subject is causing a change to the object. The structure is: Subject + 把 + Object + Verb + (other elements). It emphasizes the result of the action on the object.","explanationRu":"","examples":[{"zh":"他把书放在桌子上。","en":"He put the book on the table.","ru":"Он положил книгу на стол."},{"zh":"我把他的话记在了笔记本上。","en":"I wrote down what he said in my notebook.","ru":"Я записал то, что он сказал, в блокнот."},{"zh":"她把作业做完了。","en":"She finished her homework.","ru":"Она закончила домашнее задание."}]},{"pattern":"会","nameEn":"Auxiliary Verb 'Will' / 'Can'","explanation":"会 is used as an auxiliary verb to express future actions or abilities. It is placed before the main verb. For example, 'I will go' or 'I can go'.","explanationRu":"","examples":[{"zh":"明天我会去北京。","en":"Tomorrow I will go to Beijing.","ru":"Завтра я поеду в Пекин."},{"zh":"你会说中文吗？","en":"Can you speak Chinese?","ru":"Вы можете говорить по-китайски?"},{"zh":"他会在明天完成工作。","en":"He will finish the work tomorrow.","ru":"Он закончит работу завтра."}]},{"pattern":"不管……，都……","nameEn":"Conditional Sentence: 'No Matter... , Always...'","explanation":"This structure is used to express a condition that is true regardless of the situation. It means 'no matter what', 'regardless of', or 'always'.","explanationRu":"","examples":[{"zh":"不管天气多冷，他都坚持跑步。","en":"No matter how cold the weather is, he still insists on running.","ru":"Независимо от того, насколько холодно, он продолжает бегать."},{"zh":"不管你做什么，我都支持你。","en":"No matter what you do, I support you.","ru":"Независимо от того, что ты делаешь, я поддерживаю тебя."},{"zh":"不管遇到什么困难，我们都会一起解决。","en":"No matter what difficulties we face, we will solve them together.","ru":"Независимо от того, какие трудности мы встречаем, мы будем решать их вместе."}]},{"pattern":"只好","nameEn":"Adverb 'Had to' / 'Only Could'","explanation":"只好 is used to express that someone had no choice but to do something. It is often used after a negative situation.","explanationRu":"","examples":[{"zh":"车坏了，我只好走路去学校。","en":"The car broke down, so I had to walk to school.","ru":"Машина сломалась, поэтому я вынужден был идти пешком в школу."},{"zh":"没有其他办法，我们只好接受这个结果。","en":"There was no other way, so we had to accept the result.","ru":"Не было другого выхода, поэтому мы вынуждены были принять этот результат."},{"zh":"雨下得太大了，我们只好待在家里。","en":"It rained too heavily, so we had to stay at home.","ru":"Дождь шел слишком сильно, поэтому мы вынуждены были остаться дома."}]},{"pattern":"特别是","nameEn":"Fixed Usage: 'Especially'","explanation":"特别是 is used to emphasize a specific part of a statement. It means 'especially' or 'in particular'.","explanationRu":"","examples":[{"zh":"我喜欢吃水果，特别是苹果。","en":"I like to eat fruit, especially apples.","ru":"Мне нравится есть фрукты, особенно яблоки."},{"zh":"这个城市有很多历史建筑，特别是博物馆。","en":"This city has many historical buildings, especially museums.","ru":"В этом городе много исторических зданий, особенно музеев."},{"zh":"他很友好，特别是对小朋友。","en":"He is friendly, especially to children.","ru":"Он добрый, особенно с детьми."}]}],
  23: [{"pattern":"不得不","nameEn":"Fixed Usage","explanation":"Used to express necessity or obligation, meaning 'have to' or 'cannot help but'. It is followed by a verb. The structure is '不得不 + verb'.","explanationRu":"","examples":[{"zh":"我不得不早点起床。","en":"I have to get up early.","ru":"Мне пришлось встать пораньше."},{"zh":"他不得不放弃这个计划。","en":"He had to give up this plan.","ru":"Он вынужден был отказаться от этого плана."},{"zh":"我们不得不改变计划。","en":"We have to change the plan.","ru":"Нам пришлось изменить план."}]},{"pattern":"着","nameEn":"Aspectual Particle","explanation":"Indicates a continuous or ongoing action, often translated as 'while' or 'with'. It is placed after a verb or adjective to show that the action is happening now or is ongoing.","explanationRu":"","examples":[{"zh":"窗外下着雨。","en":"It is raining outside.","ru":"Снаружи идет дождь."},{"zh":"她穿着红色的衣服。","en":"She is wearing a red dress.","ru":"Она одета в красное платье."}]},{"pattern":"该……了","nameEn":"Fixed Pattern","explanation":"Used to express that it is time for something to happen, often translated as 'it's time to...'. The structure is '该 + verb + 了'.","explanationRu":"","examples":[{"zh":"该吃午饭了。","en":"It's time to have lunch.","ru":"Пора обедать."},{"zh":"该去上班了。","en":"It's time to go to work.","ru":"Пора идти на работу."},{"zh":"该回家了。","en":"It's time to go home.","ru":"Пора возвращаться домой."}]},{"pattern":"实在","nameEn":"Adverb","explanation":"Used to emphasize the degree of something, often translated as 'really' or 'truly'. It is placed before an adjective or adverb to intensify the meaning.","explanationRu":"","examples":[{"zh":"他实在很忙。","en":"He is really busy.","ru":"Он действительно очень занят."},{"zh":"这个电影实在有趣。","en":"This movie is really interesting.","ru":"Этот фильм очень интересный."}]},{"pattern":"终于","nameEn":"Adverb","explanation":"Indicates that something has finally happened after a long time or effort, often translated as 'finally' or 'at last'. It is placed at the beginning of a sentence or before the verb.","explanationRu":"","examples":[{"zh":"我终于找到了我的护照。","en":"I finally found my passport.","ru":"Наконец я нашел свой паспорт."},{"zh":"他终于完成了工作。","en":"He finally finished the work.","ru":"Он наконец закончил работу."},{"zh":"我们终于到家了。","en":"We finally got home.","ru":"Мы наконец приехали домой."}]}],
  24: [{"pattern":"被","nameEn":"Passive Sentence","explanation":"The passive structure uses '被' before the agent to show that the subject is acted upon. The word order is: Subject + 被 + Agent + Verb. It is used to describe actions done to the subject.","explanationRu":"","examples":[{"zh":"我的手机被偷了。","en":"My phone was stolen.","ru":"Мой телефон был украден."},{"zh":"书被我放在桌子上。","en":"The book was placed on the table by me.","ru":"Книга была поставлена на стол мной."},{"zh":"窗户被风吹开了。","en":"The window was blown open by the wind.","ru":"Окно было открыто ветром."}]},{"pattern":"只要……，就……","nameEn":"Conditional Complex Sentence","explanation":"This structure expresses a condition and its result. '只要' means 'as long as', and '就' means 'then'. The word order is: 只要 + Condition, 就 + Result. It is used to show that if the condition is met, the result will follow.","explanationRu":"","examples":[{"zh":"只要努力学习，就能取得好成绩。","en":"As long as you study hard, you can get good grades.","ru":"Если вы будете усердно учиться, вы сможете получить хорошие оценки."},{"zh":"只要天气好，我们就去公园。","en":"As long as the weather is good, we will go to the park.","ru":"Если погода будет хорошей, мы пойдем в парк."},{"zh":"只要你说，我就听。","en":"As long as you say it, I will listen.","ru":"Если ты скажешь, я буду слушать."}]},{"pattern":"别提了","nameEn":"Fixed Usage","explanation":"This phrase is used to express that something is too embarrassing or unpleasant to talk about. It literally means 'don't mention it', but is often used to mean 'don't even talk about it'.","explanationRu":"","examples":[{"zh":"我昨天在会议上说错了话，别提了。","en":"I made a mistake in the meeting yesterday, don't even talk about it.","ru":"Вчера на собрании я сказал что-то неправильно, даже не говорите об этом."},{"zh":"他考试没考好，别提了。","en":"He didn't do well on the exam, don't mention it.","ru":"Он не сдал экзамен, не упоминайте об этом."},{"zh":"我的钱包丢了，别提了。","en":"I lost my wallet, don't even talk about it.","ru":"Я потерял свой кошелек, даже не говорите об этом."}]},{"pattern":"赶紧","nameEn":"Verb","explanation":"This verb means 'to hurry' or 'to quickly'. It is used to express the need to act quickly. It is often used with other verbs to indicate urgency.","explanationRu":"","examples":[{"zh":"时间不多了，赶紧走吧。","en":"There's not much time left, hurry up and go.","ru":"Времени мало, поторопитесь и уходите."},{"zh":"他赶紧把书放回书架。","en":"He quickly put the book back on the shelf.","ru":"Он быстро положил книгу обратно на полку."},{"zh":"别担心，赶紧完成作业。","en":"Don't worry, hurry up and finish your homework.","ru":"Не беспокойтесь, поторопьтесь и закончите домашнее задание."}]},{"pattern":"特别","nameEn":"Adjective","explanation":"This adjective means 'especially' or 'particularly'. It is used to emphasize a quality or characteristic. It is often used before adjectives or adverbs.","explanationRu":"","examples":[{"zh":"这个电影特别好看。","en":"This movie is especially good.","ru":"Этот фильм особенно хорош."},{"zh":"他特别勇敢。","en":"He is especially brave.","ru":"Он особенно смел."},{"zh":"她特别喜欢这个城市。","en":"She especially likes this city.","ru":"Она особенно любит этот город."}]}],
  25: [{"pattern":"难道","nameEn":"Adverb '难道'","explanation":"Used to express surprise or doubt, often in questions. It is placed before the verb or adjective to emphasize the unexpected nature of the situation.","explanationRu":"","examples":[{"zh":"你难道不知道这件事吗？","en":"Don't you know about this matter?","ru":"Разве ты не знаешь об этом деле?"},{"zh":"他难道会不来吗？","en":"Is he really not coming?","ru":"Разве он не придет?"},{"zh":"难道你不喜欢这个礼物吗？","en":"Don't you like this gift?","ru":"Разве ты не любишь этот подарок?"}]},{"pattern":"既然……，就……","nameEn":"Causative Complex Sentence 'Since... then...'","explanation":"Used to express a cause-and-effect relationship, where the first part is the reason and the second part is the result. The structure is 'Since [reason], then [result].'","explanationRu":"","examples":[{"zh":"既然你已经来了，就坐下来吧。","en":"Since you've already come, sit down.","ru":"Поскольку ты уже пришел, садись."},{"zh":"既然天气这么好，我们就去公园吧。","en":"Since the weather is so nice, let's go to the park.","ru":"Поскольку погода такая хорошая, давай пойдем в парк."},{"zh":"既然你不喜欢，就不必勉强了。","en":"Since you don't like it, you don't have to force yourself.","ru":"Поскольку ты не любишь это, не нужно заставлять себя."}]},{"pattern":"不仅……，而且……","nameEn":"Progressive Complex Sentence 'Not only... but also...'","explanation":"Used to show that two things are true, with the second thing being stronger or more important than the first. The structure is 'Not only [first thing], but also [second thing].'","explanationRu":"","examples":[{"zh":"他不仅会说中文，而且会说英文。","en":"He not only speaks Chinese, but also speaks English.","ru":"Он не только говорит по-китайски, но и по-английски."},{"zh":"这个项目不仅节省时间，而且提高了质量。","en":"This project not only saves time but also improves quality.","ru":"Этот проект не только экономит время, но и повышает качество."},{"zh":"她不仅学习努力，而且成绩优秀。","en":"She not only studies hard but also has excellent grades.","ru":"Она не только усердно учится, но и имеет отличные оценки."}]},{"pattern":"总是","nameEn":"Adverb 'always'","explanation":"Used to indicate that something happens repeatedly or consistently. It is placed before the verb or adjective.","explanationRu":"","examples":[{"zh":"他总是很早起床。","en":"He always gets up early.","ru":"Он всегда встает рано."},{"zh":"我总是忘记带钥匙。","en":"I always forget to bring my keys.","ru":"Я всегда забываю взять ключи."},{"zh":"她总是笑，看起来很开心。","en":"She always smiles and looks happy.","ru":"Она всегда улыбается и выглядит счастливой."}]},{"pattern":"才是","nameEn":"Fixed Usage '才是'","explanation":"Used to emphasize that something is the correct or true state, often after a contrast or correction. It is placed at the end of the sentence.","explanationRu":"","examples":[{"zh":"这个答案才是正确的。","en":"This answer is the correct one.","ru":"Этот ответ и есть правильный."},{"zh":"你才是应该道歉的人。","en":"You are the one who should apologize.","ru":"Ты именно тот, кто должен извиниться."}]},{"pattern":"恐怕","nameEn":"Adverb 'probably'","explanation":"Used to express doubt or concern about something, often indicating that the speaker thinks something might not be good or true. It is placed before the verb or adjective.","explanationRu":"","examples":[{"zh":"恐怕明天会下雨。","en":"I'm afraid it will rain tomorrow.","ru":"Скорее всего, завтра пойдет дождь."},{"zh":"恐怕他不会来参加聚会。","en":"He probably won't come to the party.","ru":"Скорее всего, он не придет на вечеринку."},{"zh":"恐怕这个计划不太可行。","en":"This plan probably isn't very feasible.","ru":"Скорее всего, этот план не очень осуществим."}]}],
};
